import{_ as o}from"./chunks/PageInfo.vue_vue_type_script_setup_true_lang.CY4CSaHW.js";import{_ as a,o as c,c as r,j as d,a as i,E as s,a3 as l}from"./chunks/framework.DK8j89yW.js";import"./chunks/theme.B8gQcpPc.js";const n="/assets/image-20260406041551375.DlTZIN-o.png",h="/assets/image-20260406191907952.D940trTc.png",p="/assets/image-20260406174338868.pl9VrrU1.png",m="/assets/image-20260407054714488.CYEtDodw.png",x=JSON.parse('{"title":"AI配置","description":"","frontmatter":{},"headers":[],"relativePath":"Advance/AIConfig.md","filePath":"Advance/AIConfig.md","lastUpdated":1787059749000}'),_={name:"Advance/AIConfig.md"};function b(u,t,g,A,f,I){const e=o;return c(),r("div",null,[t[0]||(t[0]=d("h1",{id:"ai配置",tabindex:"-1"},[i("AI配置 "),d("a",{class:"header-anchor",href:"#ai配置","aria-label":'Permalink to "AI配置"'},"​")],-1)),s(e,{readTime:"2",words:"783"}),t[1]||(t[1]=l('<div class="tip custom-block"><p class="custom-block-title">💡 提醒</p><ul><li>🌐 配置 API 接口和密钥</li><li>🧠 想更换 AI 模型（GPT-4、Claude 等）</li><li>📝 需要自定义 AI 的角色定位和行为风格</li></ul></div><h2 id="配置文件位置" tabindex="-1">配置文件位置 <a class="header-anchor" href="#配置文件位置" aria-label="Permalink to &quot;配置文件位置&quot;">​</a></h2><p>AI 配置通常位于 GsCore 的配置目录中，可以通过 <a href="./../Started/WebConsole.html">WebConsole</a> 或配置文件进行设置。</p><p>建议使用 <a href="./../Started/WebConsole.html">网页控制台</a> 进行配置。</p><img src="'+n+'" alt="image-20260406041551375"><h2 id="配置一览" tabindex="-1">配置一览 <a class="header-anchor" href="#配置一览" aria-label="Permalink to &quot;配置一览&quot;">​</a></h2><h3 id="基础配置" tabindex="-1">基础配置 <a class="header-anchor" href="#基础配置" aria-label="Permalink to &quot;基础配置&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">💡 提醒</p><p>最核心的基础配置，</p><p>决定了是否启用AI、以及决定了AI的行为模式。</p><p>决定了使用什么格式的AI SDK。</p><p>也决定了Embedding提供商、Rerank提供商、网络搜索提供商。</p><p>文件位置 <code>gsuid_core\\data\\ai_core\\ai_config.json</code></p><p>建议通过网页控制台进行配置。</p></div><img src="'+h+'" alt="image-20260406191907952"><table tabindex="0"><thead><tr><th>配置项</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>enable</code></td><td><code>bool</code></td><td><code>False</code></td><td>是否启用AI服务</td></tr><tr><td><code>ai_mode</code></td><td><code>list[str]</code></td><td><code>[&quot;提及应答&quot;]</code></td><td>模型的行动入口，可以从<code>提及应答</code>, <code>定时巡检</code>, <code>趣向捕捉</code>, <code>困境救场</code> 四项中任意搭配</td></tr><tr><td><code>enable_rerank</code></td><td>bool</td><td><code>False</code></td><td>是否启用Rerank, Rerank模型可以提升RAG的检索质量，该模型大概1G左右大小，并且运行时会增加一定左右响应时间，请酌情开启</td></tr><tr><td><code>openai_provider</code></td><td><code>str</code></td><td><code>openai</code></td><td>AI模型提供商，暂时只支持选择<code>openai</code>格式，后续可能会支持<code>gemini</code>格式</td></tr><tr><td><code>embedding_provider</code></td><td><code>str</code></td><td><code>local</code></td><td>嵌入模型提供商，目前只支持选择<code>local</code>格式，会在本地使用300M左右大小的嵌入模型进行文本向量计算</td></tr><tr><td><code>websearch_provider</code></td><td><code>str</code></td><td><code>Tavily</code></td><td>网络搜索服务提供商，目前只支持<code>Tavily</code>，需要去官网申请Key使用，免费额度一个月可以进行1000次搜索</td></tr><tr><td><code>multi_agent_lenth</code></td><td><code>int</code></td><td><code>12</code></td><td>最多允许AI思考轮数，注意太大的话如果死循环将会消耗非常多的token</td></tr><tr><td><code>white_list</code></td><td><code>list[str]</code></td><td><code>[]</code></td><td>指定白名单, 只有白名单中的用户才能使用AI服务</td></tr><tr><td><code>black_list</code></td><td><code>list[str]</code></td><td><code>[]</code></td><td>指定黑名单, 黑名单中的用户将不能使用AI服务</td></tr></tbody></table><h3 id="模型配置" tabindex="-1">模型配置 <a class="header-anchor" href="#模型配置" aria-label="Permalink to &quot;模型配置&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">🚨 警告</p><p>目前仅提供OpenAI SDK兼容的接口</p><p>文件位置 <code>gsuid_core\\data\\ai_core\\openai_config.json</code></p><p>建议通过网页控制台进行配置</p></div><img src="'+p+'" alt="image-20260406174338868"><table tabindex="0"><thead><tr><th>配置项</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>base_url</code></td><td><code>str</code></td><td>-</td><td>API 基础 URL</td></tr><tr><td><code>model_name</code></td><td><code>str</code></td><td>-</td><td>AI 模型名称，如 <code>gpt-4</code>、<code>claude-3</code> 等</td></tr><tr><td><code>api_key</code></td><td><code>str</code></td><td>-</td><td>API 密钥</td></tr><tr><td><code>model_support</code></td><td><code>list[str]</code></td><td><code>[&quot;text&quot;]</code></td><td>模型支持的能力, 可以从<code>text</code>, <code>image</code>, <code>audio</code>, <code>video</code> 四项中任意搭配</td></tr></tbody></table><h3 id="网络搜索配置" tabindex="-1">网络搜索配置 <a class="header-anchor" href="#网络搜索配置" aria-label="Permalink to &quot;网络搜索配置&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">🚨 警告</p><p>目前仅提供Tavily的网络搜索功能, 请先前往 <a href="https://tavily.com" target="_blank" rel="noreferrer">https://tavily.com</a> 获取 API Key</p><p>文件位置 <code>gsuid_core\\data\\ai_core\\tavily_config.json</code></p><p>建议通过网页控制台进行配置</p></div><img src="'+m+'" alt="image-20260407054714488"><table tabindex="0"><thead><tr><th>配置项</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>api_key</code></td><td><code>str</code></td><td>-</td><td>Tavily API密钥</td></tr><tr><td><code>max_results</code></td><td><code>int</code></td><td>10</td><td>指定每次搜索的最大返回结果数量</td></tr><tr><td><code>search_depth</code></td><td><code>str</code></td><td><code>basic</code></td><td>指定搜索深度，basic 速度更快但结果较少，advanced 更详细但速度较慢</td></tr></tbody></table><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="./Tools.html">工具注册</a> - 学习如何注册 AI 工具</li><li><a href="./Agent.html">Agent创建</a> - 了解临时 Agent 的更多用法</li></ul>',20))])}const y=a(_,[["render",b]]);export{x as __pageData,y as default};
